  const uuids = [...grantUuids(clsDoc, 5), ...grantUuids(subDoc, 5)];

  const spcE = findIn(orgIdx, s.species, "race");
  if (spcE) { const d = await ORG.getDocument(spcE._id); const dd = d.toObject(); delete dd._id; toAdd.push(dd); uuids.push(...grantUuids(d, 5)); }
  else notes.push(`species '${s.species}' not found`);
  const bgE = findIn(orgIdx, s.bg, "background");
  if (bgE) { const d = await ORG.getDocument(bgE._id); const dd = d.toObject(); delete dd._id; toAdd.push(dd); }
  else notes.push(`background '${s.bg}' not found`);

  const failed = [];
  for (const u of [...new Set(uuids)]) {
    const doc = await fromUuid(u);
    if (!doc) { failed.push(u); continue; }
    const d = doc.toObject(); delete d._id; toAdd.push(d);
  }
  for (const an of s.armor) {
    const e = findEq(an);
    if (!e) { notes.push(`armor '${an}' not found`); continue; }
    const d = (await EQP.getDocument(e._id)).toObject(); delete d._id;
    d.system.equipped = true;
    toAdd.push(d);
  }
  await actor.createEmbeddedDocuments("Item", toAdd);
  await actor.update({ "system.attributes.hp.max": s.hp, "system.attributes.hp.value": s.hp });

  const a = game.actors.get(actor.id);
  report.push({
    name: a.name,
    build: `${a.items.find(i => i.type === "class")?.name} 5 / ${a.items.find(i => i.type === "subclass")?.name}`,
    species: a.items.find(i => i.type === "race")?.name ?? "—",
    bg: a.items.find(i => i.type === "background")?.name ?? "—",
    feats: a.items.filter(i => i.type === "feat").length,
    hp: a.system.attributes.hp.max,
    ac: a.system.attributes.ac.value,
    items: a.items.size,
    failed, notes
  });
}
return report;

