const study = await import("/modules/pentaryn-ties/study.mjs");
const pc = game.actors.getName("Ballad Quinn");
const own = canvas.tokens.placeables.find(t => t.document.actorId === pc.id);
const target = canvas.tokens.placeables.find(t => t.actor && t.document.actorId !== pc.id).actor;
const startX = own.document.x, startY = own.document.y;
const size = canvas.scene.grid.size, feet = canvas.scene.grid.distance;
const px = ft => Math.round((ft / feet) * size);
const out = {};
try {
  study.clearScoping();
  for (let i = 0; i < 4; i++) await study.inspectAs(pc, target);
  out.standingStill = study.scopingState(pc.id)?.count;

  // a small shuffle — 5 ft, under the 15 ft threshold — must NOT reset
  await own.document.update({ x: startX + px(5) }, { animate: false });
  await study.inspectAs(pc, target);
  out.afterShuffling5ft = study.scopingState(pc.id)?.count;

  // moving on — 25 ft from where the run began — must reset to 1
  await own.document.update({ x: startX + px(25) }, { animate: false });
  await study.inspectAs(pc, target);
  out.afterMoving25ft = study.scopingState(pc.id)?.count;
  out.anchorMovedWithThem = study.scopingState(pc.id)?.anchor;

  // and a scene change wipes it entirely — you are not "still standing there" elsewhere
  study.clearScoping();
  out.afterSceneChange = study.scopingState(pc.id) ?? "cleared";
  return { ...out, resetWorks: out.afterMoving25ft === 1, shuffleDoesNotReset: out.afterShuffling5ft === 5 };
} finally {
  await own.document.update({ x: startX, y: startY }, { animate: false });
  study.clearScoping();
}

const study = await import("/modules/pentaryn-ties/study.mjs");
const pc = game.actors.getName("Ballad Quinn");
const target = canvas.tokens.placeables.find(t => t.actor && t.document.actorId !== pc.id)?.actor;
if (!target) return { skipped: "no target on this scene" };
const combat = game.combat;
const saved = { round: combat?.round, turn: combat?.turn };
const out = { savedCombat: saved };

// build up a run
study.clearScoping();
for (let i = 0; i < 4; i++) await study.inspectAs(pc, target);
out.beforeCombat = study.scopingState(pc.id)?.count;

// ── combat starting must end it ──
if (combat) {
  await combat.update({ round: 0, turn: null });
  await new Promise(r => setTimeout(r, 400));
  study.clearScoping();
  for (let i = 0; i < 3; i++) await study.inspectAs(pc, target);
  out.runRebuiltBeforeStart = study.scopingState(pc.id)?.count;

  await combat.startCombat();
  await new Promise(r => setTimeout(r, 800));
  out.afterCombatStart = study.scopingState(pc.id) ?? "cleared";

  // ── and ending it ──
  study.clearScoping();
  for (let i = 0; i < 3; i++) await study.inspectAs(pc, target);
  out.runRebuiltDuringCombat = study.scopingState(pc.id)?.count;
}
