return {
  getDurationSource: m ? m[0] : "(not found in class source)",
  hookExists: "chatBubble",
  // the hook signature, which is where a duration could be influenced
  hookMention: cls.match(/.{0,200}Hooks\.call(All)?\("chatBubble".{0,200}/)?.[0] ?? null
};

